/**
 * 纳音五行算法
 *
 * 纳音是根据干支组合推算出的五行属性，每两个干支组成一个纳音。
 * 共有60个干支组合，对应30种纳音五行。
 *
 * 纳音五行分为：
 * - 金：海中金、金箔金、白蜡金、剑锋金、钗钏金、沙中金
 * - 木：大林木、杨柳木、松柏木、平地木、石榴木、桑柘木
 * - 水：涧下水、大溪水、长流水、天河水、大海水、泉中水
 * - 火：炉中火、山头火、霹雳火、山下火、覆灯火、天上火
 * - 土：城头土、屋上土、壁上土、大驿土、沙中土、路旁土
 */
import type { Tiangan, Dizhi } from './types';
/**
 * 纳音五行类型
 */
export type NaYin = '海中金' | '金箔金' | '白蜡金' | '剑锋金' | '钗钏金' | '沙中金' | '大林木' | '杨柳木' | '松柏木' | '平地木' | '石榴木' | '桑柘木' | '涧下水' | '大溪水' | '长流水' | '天河水' | '大海水' | '泉中水' | '炉中火' | '山头火' | '霹雳火' | '山下火' | '覆灯火' | '天上火' | '城头土' | '屋上土' | '壁上土' | '大驿土' | '沙中土' | '路旁土';
/**
 * 获取干支的纳音五行
 * @param tiangan 天干
 * @param dizhi 地支
 * @returns 纳音五行
 */
export declare function getNaYin(tiangan: Tiangan, dizhi: Dizhi): NaYin;
/**
 * 批量获取四柱的纳音
 * @param siZhu 四柱干支
 * @returns 四柱纳音数组
 */
export declare function getSiZhuNaYin(siZhu: {
    year: {
        gan: Tiangan;
        zhi: Dizhi;
    };
    month: {
        gan: Tiangan;
        zhi: Dizhi;
    };
    day: {
        gan: Tiangan;
        zhi: Dizhi;
    };
    hour: {
        gan: Tiangan;
        zhi: Dizhi;
    };
}): {
    year: NaYin;
    month: NaYin;
    day: NaYin;
    hour: NaYin;
};
/**
 * 获取纳音的五行属性
 * @param nayin 纳音
 * @returns 五行属性（金木水火土）
 */
export declare function getNaYinWuXing(nayin: NaYin): '金' | '木' | '水' | '火' | '土';
/**
 * 获取纳音五行的相生相克关系
 * @param nayin1 纳音1
 * @param nayin2 纳音2
 * @returns 关系（生、克、比和）
 */
export declare function getNaYinRelation(nayin1: NaYin, nayin2: NaYin): '生' | '克' | '被生' | '被克' | '比和';
